"""Catalogues of everyday objects, furniture, room contents, tabletop items, outdoor street items, toys and held items.
Used by objects_build.py (generates obj_* files, acc_props, env_props) and by fix_settings.py (replacement 'extra' clauses for settings10000).
Rubber ducks are ONE toy among ~200 here (about 0.04% of toy lines), instead of the 1-in-120 setting lines they used to appear in."""
import random
def art(s):
    last = s.split()[-1].lower()
    if " of " not in s and " with " not in s and " on a " not in s and last.endswith("s") and not last.endswith(("ss", "us", "is", "ous")): return "some " + s
    return ("an " if s[0].lower() in "aeiou" else "a ") + s

