# ---------------- extra clauses for setting lines (what the old 'whimsical' tail clauses are replaced with) ----------------
def extra_clauses(n, seed=1):
    R = random.Random(seed); out = []
    seen = set()
    makers = [lambda: f"{R.choice(T_ITEM)} on a nearby surface", lambda: f"{R.choice(O_ITEM)} close by", lambda: f"{art(R.choice(R_ITEM))} {R.choice(R_STATE)}",
              lambda: f"{R.choice(TOYS)} lying nearby" if R.random() < .5 else f"{R.choice(TOYS)} left on the ground",
              lambda: f"{art(R.choice(F_STYLE) + ' ' + R.choice(F_TYPE))} {R.choice(F_PLACE)}", lambda: f"{R.choice(O_ITEM)} in the background",
              lambda: f"{art(R.choice(R_ITEM))} within reach", lambda: f"{R.choice(T_ITEM)} within reach"]
    while len(out) < n:
        c = R.choice(makers)()
        c = c[0].lower() + c[1:] if c[:2] not in ('A ', 'An') else c
        if c not in seen: seen.add(c); out.append(c)
    return out
